// chart.json is generated by scripts/build-chart.mjs, and a decision stored against a chart
// version must always mean the same questions. These tests fail when the two drift apart, or
// when the questions change without the version.
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { createHash } from 'node:crypto';
import { readFileSync } from 'node:fs';
import { buildChart, nodesHash, readLedger, CHART_PATH, VERSION, NODES } from '../scripts/build-chart.mjs';

test('chart.json is exactly what build-chart.mjs builds', () => {
  assert.deepEqual(JSON.parse(readFileSync(CHART_PATH, 'utf8')), buildChart());
});

test('chart-versions.json records these questions under this version', () => {
  const ledger = readLedger();
  assert.equal(
    ledger[VERSION],
    nodesHash(),
    `the questions changed since version ${VERSION} was recorded: bump VERSION in scripts/build-chart.mjs and rerun it`,
  );
});

test('no two versions in the ledger share a hash', () => {
  const hashes = Object.values(readLedger());
  assert.equal(new Set(hashes).size, hashes.length);
});

test('changing one question changes the hash', () => {
  const changed = structuredClone(NODES);
  changed[0][1] = `${changed[0][1]} (changed)`;
  const other = createHash('sha256').update(JSON.stringify(changed)).digest('hex');
  assert.notEqual(other, nodesHash());
});
